  border-color: transparent;
}
.budgie-menu button:not(.category-button) {
  padding-top: 5px;
  padding-bottom: 5px;
  border-radius: 0;
  box-shadow: none;
}
.budgie-menu undershoot, .budgie-menu overshoot {
  background: none;
}

button.budgie-menu-launcher {
  padding: 0 2px;
  color: #c0c0c0;
  box-shadow: none;
  background-color: transparent;
}
button.budgie-menu-launcher:hover {
